import numpy as np
def read(f):
    L=open(f).read().split('\n')[2:104]
    return [l.split()[0] for l in L], np.array([[float(x) for x in l.split()[1:]] for l in L])
cov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Cl':1.02,'Ru':1.46}
def bonds(S,P):
    b=set()
    for i in range(len(S)):
        for j in range(i+1,len(S)):
            if np.linalg.norm(P[i]-P[j]) < 1.25*(cov[S[i]]+cov[S[j]]): b.add((i,j))
    return b
S,P0=read('init.xyz'); _,P1=read('opt1.xyz')
b0,b1=bonds(S,P0),bonds(S,P1)
print('lost',[(S[i],S[j],i,j) for i,j in b0-b1]); print('new',[(S[i],S[j],i,j) for i,j in b1-b0])
# check chirality sign at CH carbons: 3 (C2=13,P=4,Cim=1) and 23 (19,24,33)
for c,a,b,d in [(3,13,4,1),(23,19,24,33)]:
    v=np.dot(np.cross(P1[a]-P1[c],P1[b]-P1[c]),P1[d]-P1[c]); print(c,round(v,2))
"
